'use strict';
/**
 * Development, social, personality and emotion paradigms (A8):
 * conservation, false_belief, asch, prisoners_dilemma, ipip_big5, face_recognition.
 * Contract: docs/EXPERIMENT_API.md. Characters, wording and faces are original/procedural.
 * Child behaviour, bot behaviour and cohort data are generated by models and labelled "Simulated".
 */
const S = require('../../psych/stats.js');
const PM = require('../../psych/psychometrics.js');
const { drawRT, drawCorrect, cohort } = require('../../psych/participants.js');
const { drawFace, EMOTIONS, look } = require('../../people/face2d.js');

const DEV = { week: 11, panel: 'development', zone: 'childdev', apa: '1.2', domain: 'Dev', hec: 'S4 Developmental Psychology' };
const SOC = { week: 14, panel: 'social', zone: 'mohalla', apa: '1.1', domain: 'Social', hec: 'S3 Social Psychology' };

const text = (ctx, s, x, y, size = 20, color = '#111', weight = 600, align = 'center') => { ctx.fillStyle = color; ctx.font = `${weight} ${size}px system-ui, sans-serif`; ctx.textAlign = align; ctx.textBaseline = 'middle'; ctx.fillText(s, x, y); };
function wrap(ctx, s, x, y, maxW, size = 20, color = '#111', weight = 500, align = 'center', lineH = 1.35) {
  ctx.font = `${weight} ${size}px system-ui, sans-serif`;
  const words = String(s).split(/\s+/); const lines = []; let cur = '';
  for (const w of words) { const t = cur ? cur + ' ' + w : w; if (ctx.measureText(t).width > maxW && cur) { lines.push(cur); cur = w; } else cur = t; }
  if (cur) lines.push(cur);
  lines.forEach((l, i) => text(ctx, l, x, y + i * size * lineH, size, color, weight, align));
  return y + lines.length * size * lineH;
}
function bubble(ctx, s, x, y, maxW, size = 16) {
  ctx.font = `500 ${size}px system-ui, sans-serif`;
  const w = Math.min(maxW, ctx.measureText(s).width + 24), lines = Math.max(1, Math.ceil((ctx.measureText(s).width + 24) / maxW));
  const h = lines * size * 1.35 + 14;
  ctx.fillStyle = '#fff'; ctx.strokeStyle = '#334155'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.rect(x - w / 2, y - h, w, h); ctx.fill(); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x - 6, y); ctx.lineTo(x, y + 10); ctx.lineTo(x + 6, y); ctx.fill();
  wrap(ctx, s, x, y - h + 7 + size * 0.68, w - 16, size, '#111', 500);
}
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const pct = (v) => (Number.isFinite(v) ? (v * 100).toFixed(0) + '%' : '—');
const meanOr = (xs, d = NaN) => (xs.length ? S.mean(xs) : d);
const logistic = (x) => 1 / (1 + Math.exp(-x));
const isOk = (r) => String(r.correct) === '1';
const field = (s, k) => { const m = new RegExp(k + '=([^;:|]+)').exec(String(s)); return m ? m[1] : ''; };

/** Small seeded generator for simulated cohorts / tournaments inside analyse. */
function mkRng(seed) {
  let a = seed >>> 0;
  const random = () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  return { random, normal(mu = 0, s = 1) { let u, v, q; do { u = random() * 2 - 1; v = random() * 2 - 1; q = u * u + v * v; } while (q >= 1 || q === 0); return mu + s * u * Math.sqrt(-2 * Math.log(q) / q); } };
}

function glass(ctx, x, base, w, h, level) {
  ctx.fillStyle = 'rgba(86,180,233,0.75)'; ctx.fillRect(x - w / 2, base - h * level, w, h * level);
  ctx.strokeStyle = '#334155'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(x - w / 2, base - h); ctx.lineTo(x - w / 2, base); ctx.lineTo(x + w / 2, base); ctx.lineTo(x + w / 2, base - h); ctx.stroke();
}

// ---------------------------------------------------------------- Piaget conservation (observe / code)
const CONS_ANSWERS = {
  conserve: ['They’re the same. You only poured it — nothing was added or taken away.', 'Same! That glass is taller but it’s thinner.', 'The same, because if you pour it back it will look like before.'],
  nonconserve: ['This one has more, because it’s taller!', 'The tall one. The water goes up higher.', 'That one has more… look how high it is.'],
  same_noreason: ['Umm… they’re the same.', 'The same, I think.'],
};
const conservation = Object.assign({
  id: 'conservation', title: 'Piaget conservation (observe/code)',
  purpose: 'To practise coding children’s answers in a liquid-conservation task and to check your coding reliability against an expert key (Cohen’s κ).',
  instructions: '<p>Watch a <b>simulated child</b> see water poured from a short wide glass into a tall thin glass, then read the child’s answer. Code it (keys <kbd>1</kbd>/<kbd>2</kbd>):</p><ul><li><b>Conserves</b> — says the amounts are the <b>same</b> AND gives a reason (nothing added/removed, it could be poured back, or taller-but-thinner).</li><li><b>Does not conserve</b> — says one has more, or says "same" with no reason at all.</li></ul><p>All children are simulated; their answers come from a model, not real children.</p>',
  estimateMin: 4, practice: 0, fix: 300, iti: 500, timeout: null, background: '#f1f5f9', animated: true,
  response: { type: 'choice', choices: [{ value: 'conserves', label: 'Conserves' }, { value: 'not', label: 'Does not conserve' }] },
  factRefs: ['F-PIAGET'],
  buildTrials(rng, opts) {
    const n = opts.trials || (opts.quick ? 8 : 16);
    const ages = []; while (ages.length < n) ages.push(...rng.shuffle([4, 5, 6, 7, 8]));
    return ages.slice(0, n).map((age, i) => {
      const cons = rng.random() < logistic((age - 6.2) * 1.6); // Simulated age model (illustrative)
      const type = cons ? 'conserve' : rng.random() < 0.3 ? 'same_noreason' : 'nonconserve';
      const key = type === 'conserve' ? 'conserves' : 'not';
      return { condition: 'age' + age, age, type, answer: rng.pick(CONS_ANSWERS[type]), look: (i * 3 + age) % 13, correctResponse: key, stimulus: `age=${age};type=${type};key=${key}` };
    });
  },
  draw(ctx, t, W, H, elapsed) {
    drawFace(ctx, W * 0.18, H * 0.42, 170, { 1: 0.3 }, Object.assign(look(t.look), { gaze: { x: 0.8, y: 0.2 }, label: `Simulated child, age ${t.age}` }));
    const base = H * 0.62, pour = clamp((elapsed - 1200) / 1800, 0, 1);
    glass(ctx, W * 0.45, base, 80, 110, 0.6);
    glass(ctx, W * 0.62, base, 80, 110, 0.6 * (1 - pour));
    glass(ctx, W * 0.8, base, 40, 220, 0.6 * pour);
    text(ctx, 'A', W * 0.45, base + 22, 16); text(ctx, 'B', W * 0.62, base + 22, 16); text(ctx, 'C (tall)', W * 0.8, base + 22, 16);
    if (elapsed < 1200) text(ctx, 'Glasses A and B hold the same amount.', W * 0.62, 50, 20);
    else if (elapsed < 3000) text(ctx, 'B is poured into the tall glass C…', W * 0.62, 50, 20);
    else text(ctx, '"Do A and C have the same amount to drink, or does one have more?"', W * 0.6, 50, 19, '#0F766E', 600);
    if (elapsed >= 3600) bubble(ctx, t.answer, W * 0.22, H * 0.2, W * 0.36, 16);
    text(ctx, 'Code the answer: 1 = conserves, 2 = does not conserve', W / 2, H - 40, 17, '#334155', 500);
  },
  score(t, r) { return r == null ? false : r === t.correctResponse; },
  simulate(p, t, rng) {
    const ok = drawCorrect(p, rng, t.type === 'same_noreason' ? 2.6 : 0.3);
    return { response: ok ? t.correctResponse : (t.correctResponse === 'conserves' ? 'not' : 'conserves'), rt: 3600 + drawRT(p, rng, { mu: 1500 }).rt };
  },
  analyse(rows) {
    const coded = rows.filter((r) => r.response !== '');
    const acc = meanOr(coded.map((r) => (isOk(r) ? 1 : 0)));
    const cat = ['conserves', 'not'];
    const table = [[0, 0], [0, 0]];
    coded.forEach((r) => { const e = cat.indexOf(field(r.stimulus, 'key')), y = cat.indexOf(r.response); if (e >= 0 && y >= 0) table[e][y]++; });
    const k = coded.length ? PM.kappaFromTable(table) : { kappa: NaN, po: NaN };
    const byType = (ty) => meanOr(coded.filter((r) => field(r.stimulus, 'type') === ty).map((r) => (isOk(r) ? 1 : 0)));
    const ages = [4, 5, 6, 7, 8];
    const consRate = ages.map((a) => meanOr(rows.filter((r) => r.condition === 'age' + a).map((r) => (field(r.stimulus, 'key') === 'conserves' ? 1 : 0))));
    const lines = [
      `Coding accuracy vs expert key: ${pct(acc)} (${coded.length} answers)`,
      Number.isFinite(k.kappa) ? `Cohen's κ = ${k.kappa.toFixed(2)} (observed agreement ${pct(k.po)}, chance ${pct(k.pe)})` : 'Cohen’s κ undefined here (all answers fell in one category).',
      `Accuracy by answer type — reasoned "same": ${pct(byType('conserve'))}, "one has more": ${pct(byType('nonconserve'))}, "same" with no reason: ${pct(byType('same_noreason'))}`,
      `Simulated data — children who conserved, by age: ${ages.map((a, i) => `${a} y ${pct(consRate[i])}`).join(', ')}`,
      'Ages in Piaget’s account are approximate (F-PIAGET, under verification); sequence matters more than exact age.',
    ];
    return { lines, stats: { accuracy: acc, kappa: k.kappa },
      chart: (ch) => ch.bar(ages.map((a, i) => ({ name: a + ' y', value: (consRate[i] || 0) * 100 })), { label: 'Simulated data: % of simulated children conserving, by age', yl: '%', yr: [0, 100] }) };
  },
}, DEV);

// ---------------------------------------------------------------- false belief (Zara & Bilal)
const FB_SAY = { basket: ['In the basket! She put it there and didn’t see.', 'Basket — she thinks it’s still there.'], box: ['In the box! Because the ball is in the box.', 'Box. Bilal put it there.'] };
function drawStory(ctx, W, H, elapsed) {
  const floor = H * 0.68, bx = W * 0.32, xx = W * 0.62;
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(0, floor, W, H - floor);
  // basket
  ctx.fillStyle = '#b45309'; ctx.beginPath(); ctx.moveTo(bx - 50, floor - 60); ctx.lineTo(bx + 50, floor - 60); ctx.lineTo(bx + 38, floor); ctx.lineTo(bx - 38, floor); ctx.closePath(); ctx.fill();
  text(ctx, 'basket', bx, floor + 20, 15, '#7c2d12');
  // box
  ctx.fillStyle = '#0072B2'; ctx.fillRect(xx - 45, floor - 70, 90, 70); ctx.fillStyle = '#075985'; ctx.fillRect(xx - 50, floor - 78, 100, 12);
  text(ctx, 'box', xx, floor + 20, 15, '#075985');
  // Zara: present 0–1500 and after 4000
  const zaraHere = elapsed < 1800 || elapsed >= 4000;
  if (zaraHere) drawFace(ctx, W * 0.12, floor - 120, 130, elapsed >= 4000 ? { 1: 0.2 } : { 6: 0.4, 12: 0.6 }, Object.assign(look(1), { label: 'Zara' }));
  else text(ctx, 'Zara has gone out to play.', W * 0.14, floor - 140, 15, '#334155', 600);
  if (elapsed >= 2200 && elapsed < 4600) drawFace(ctx, W * 0.86, floor - 120, 130, { 6: 0.3, 12: 0.4 }, Object.assign(look(2), { label: 'Bilal' }));
  // ball path: Zara → basket (0–1500); basket → box (2600–3800)
  let x, y;
  if (elapsed < 1500) { const f = elapsed / 1500; x = W * 0.16 + (bx - W * 0.16) * f; y = floor - 110 + 60 * f; }
  else if (elapsed < 2600) { x = bx; y = floor - 50; }
  else if (elapsed < 3800) { const f = (elapsed - 2600) / 1200; x = bx + (xx - bx) * f; y = floor - 50 - Math.sin(f * Math.PI) * 70 - 10 * f; }
  else { x = xx; y = floor - 60; }
  if (!(elapsed >= 3800)) { ctx.fillStyle = '#D55E00'; ctx.beginPath(); ctx.arc(x, y, 13, 0, Math.PI * 2); ctx.fill(); }
  const cap = elapsed < 1500 ? 'Zara puts her ball in the basket.' : elapsed < 2600 ? 'Zara goes outside.' : elapsed < 4000 ? 'While she is away, Bilal moves the ball into the box.' : 'Zara comes back to get her ball.';
  text(ctx, cap, W / 2, 40, 20, '#111', 600);
}
const falseBelief = Object.assign({
  id: 'false_belief', title: 'False-belief (original characters)',
  purpose: 'To see how understanding of false belief changes with age by predicting and coding simulated children’s answers in a change-of-location story.',
  instructions: '<p>A short change-of-location story (in the style of the classic Sally–Anne task, with original characters <b>Zara</b> and <b>Bilal</b>): Zara leaves her ball in the <b>basket</b>; while she is away Bilal moves it to the <b>box</b>.</p><p>First <b>predict</b> where a simulated child aged 3–5 will say Zara looks. Then read the child’s answer and <b>code</b> it: <b>pass</b> = says "basket" (where Zara <i>thinks</i> it is); <b>fail</b> = says "box" (where it really is).</p><p>Children are simulated by an age model — Simulated data.</p>',
  estimateMin: 4, practice: 0, fix: 300, iti: 500, timeout: null, background: '#f8fafc', animated: true,
  response: { type: 'choice' },
  factRefs: ['F-BARON'],
  buildTrials(rng, opts) {
    const kids = Math.max(2, Math.ceil((opts.trials || (opts.quick ? 8 : 16)) / 2));
    const ages = []; while (ages.length < kids) ages.push(...rng.shuffle([3, 4, 5]));
    const out = [];
    ages.slice(0, kids).forEach((age, k) => {
      const passes = rng.random() < logistic((age - 4.0) * 2.0); // Simulated age model (illustrative)
      const said = passes ? 'basket' : 'box';
      const base = { condition: 'age' + age, age, said, child: k + 1, look: (k * 5 + 3) % 11 };
      out.push(Object.assign({}, base, { phase: 'predict', choices: [{ value: 'basket', label: 'Child will say: basket' }, { value: 'box', label: 'Child will say: box' }], correctResponse: said, stimulus: `predict:child${k + 1}:age=${age}:said=${said}` }));
      out.push(Object.assign({}, base, { phase: 'code', answer: rng.pick(FB_SAY[said]), choices: [{ value: 'pass', label: 'Pass (false-belief answer)' }, { value: 'fail', label: 'Fail (reality answer)' }], correctResponse: passes ? 'pass' : 'fail', stimulus: `code:child${k + 1}:age=${age}:said=${said}` }));
    });
    return out;
  },
  draw(ctx, t, W, H, elapsed) {
    if (t.phase === 'predict') {
      drawStory(ctx, W, H, elapsed);
      if (elapsed >= 4000) wrap(ctx, `A simulated child (age ${t.age}) is asked: "Where will Zara look for her ball?" — What will the child say?`, W / 2, H - 70, W * 0.85, 18, '#0F766E', 600);
    } else {
      drawFace(ctx, W * 0.3, H * 0.52, 200, { 6: 0.3, 12: 0.4, 25: 0.4 }, Object.assign(look(t.look), { label: `Simulated child ${t.child}, age ${t.age}` }));
      text(ctx, 'Question: "Where will Zara look for her ball?"', W / 2, 50, 20, '#111', 600);
      bubble(ctx, t.answer, W * 0.62, H * 0.42, W * 0.4, 18);
      text(ctx, 'Code: 1 = pass (basket), 2 = fail (box)', W / 2, H - 40, 17, '#334155', 500);
    }
  },
  score(t, r) { return r == null ? false : r === t.correctResponse; },
  simulate(p, t, rng) {
    if (t.phase === 'predict') return { response: rng.random() < clamp(0.15 + (t.age - 3) * 0.35, 0.05, 0.95) ? 'basket' : 'box', rt: 4200 + drawRT(p, rng, { mu: 1200 }).rt };
    const ok = drawCorrect(p, rng, 0.2);
    return { response: ok ? t.correctResponse : (t.correctResponse === 'pass' ? 'fail' : 'pass'), rt: drawRT(p, rng, { mu: 1400 }).rt };
  },
  analyse(rows) {
    const code = rows.filter((r) => /^code:/.test(r.stimulus)), pred = rows.filter((r) => /^predict:/.test(r.stimulus));
    const ages = [3, 4, 5];
    const pass = ages.map((a) => meanOr(code.filter((r) => r.condition === 'age' + a).map((r) => (field(r.stimulus, 'said') === 'basket' ? 1 : 0))));
    const n = ages.map((a) => code.filter((r) => r.condition === 'age' + a).length);
    const pAcc = meanOr(pred.filter((r) => r.response !== '').map((r) => (isOk(r) ? 1 : 0)));
    const cAcc = meanOr(code.filter((r) => r.response !== '').map((r) => (isOk(r) ? 1 : 0)));
    const lines = [
      `Simulated data — false-belief pass rate by age: ${ages.map((a, i) => `${a} y ${pct(pass[i])} (n=${n[i]})`).join(', ')}`,
      `Your predictions matched the child’s actual answer: ${pct(pAcc)}`,
      `Your pass/fail coding accuracy: ${pct(cAcc)}`,
      'Original paradigm: Baron-Cohen, Leslie & Frith (1985), F-BARON. Passing requires representing a belief that differs from reality.',
    ];
    return { lines, stats: { passByAge: pass, predictionAccuracy: pAcc, codingAccuracy: cAcc },
      chart: (ch) => ch.bar(ages.map((a, i) => ({ name: a + ' y', value: (pass[i] || 0) * 100 })), { label: 'Simulated data: false-belief pass rate by age', yl: '%', yr: [0, 100] }) };
  },
}, DEV);

// ---------------------------------------------------------------- Asch-style conformity (deception, debriefed)
const CONF_NAMES = ['Hamza', 'Ayesha', 'Daniyal', 'Sana', 'Faraz'];
const asch = Object.assign({
  id: 'asch', title: 'Asch-style conformity (debriefed)',
  purpose: 'To study how judgements of line length are made in a group where other people answer aloud first.',
  instructions: '<p>Look at the <b>standard line</b> on the left. Which comparison line — <b>A</b>, <b>B</b> or <b>C</b> — is the same length? The five other participants answer first; then it is your turn (keys <kbd>1</kbd>–<kbd>3</kbd>).</p>',
  estimateMin: 4, practice: 0, fix: 300, iti: 700, timeout: null, background: '#f8fafc', animated: true,
  response: { type: 'choice', choices: ['A', 'B', 'C'] },
  deception: true,
  debrief: {
    deception: 'The five other "participants" were scripted computer agents, not people. On the critical trials they were programmed to all give the same wrong answer before you answered.',
    purpose: 'This recreates, in a mild form, the classic Asch line-judgement paradigm on conformity to a unanimous majority. Being told the truth beforehand would have removed the social pressure being studied. Going along with the group sometimes is a common, normal response — it says nothing bad about you.',
    safeguards: 'Minimal risk, no real audience, data stay on this device, and you can delete this run’s data now. Deception is used only because the question cannot be answered otherwise, and you are debriefed immediately (APA Ethics Code 8.07, 8.08).',
  },
  factRefs: ['F-ASCH'],
  buildTrials(rng, opts) {
    const n = opts.trials || (opts.quick ? 9 : 18);
    const nCrit = Math.round(n * 2 / 3);
    const lead = Math.min(2, n - nCrit);
    const rest = rng.shuffle(Array.from({ length: n - lead }, (_, i) => (i < nCrit ? 'critical' : 'neutral')));
    const conds = Array.from({ length: lead }, () => 'neutral').concat(rest);
    return conds.map((condition) => {
      const std = rng.int(8, 16) * 10;
      const lens = rng.shuffle([std, Math.round(std * rng.uniform(0.6, 0.8)), Math.round(std * rng.uniform(1.22, 1.45))]);
      const labels = ['A', 'B', 'C'];
      const correct = labels[lens.indexOf(std)];
      const wrong = labels.filter((l) => l !== correct);
      const conf = condition === 'critical' ? rng.pick(wrong) : correct;
      return { condition, std, lens, conf, correctResponse: correct, stimulus: `${condition}:std=${std};A=${lens[0]};B=${lens[1]};C=${lens[2]};conf=${conf};correct=${correct}` };
    });
  },
  draw(ctx, t, W, H, elapsed) {
    const top = H * 0.12, sc = (H * 0.32) / 160;
    ctx.fillStyle = '#fff'; ctx.fillRect(W * 0.08, top, W * 0.2, H * 0.4); ctx.fillRect(W * 0.38, top, W * 0.54, H * 0.4);
    ctx.fillStyle = '#111';
    ctx.fillRect(W * 0.18 - 3, top + H * 0.36 - t.std * sc, 6, t.std * sc);
    text(ctx, 'standard', W * 0.18, top + H * 0.38, 14, '#334155', 600);
    t.lens.forEach((L, i) => { const x = W * (0.47 + i * 0.18); ctx.fillStyle = '#111'; ctx.fillRect(x - 3, top + H * 0.36 - L * sc, 6, L * sc); text(ctx, 'ABC'[i], x, top + H * 0.38, 18, '#111', 800); });
    const fy = H * 0.73;
    for (let i = 0; i < 5; i++) {
      const x = W * (0.1 + i * 0.16), said = elapsed >= 600 * (i + 1);
      drawFace(ctx, x, fy, 95, said && elapsed < 600 * (i + 1) + 400 ? { 25: 0.5, 26: 0.3 } : {}, Object.assign(look(i + 3), { label: CONF_NAMES[i] }));
      if (said) bubble(ctx, `"${t.conf}"`, x, fy - 62, 80, 18);
    }
    const yx = W * 0.9;
    ctx.fillStyle = elapsed >= 3300 ? '#0F766E' : '#94a3b8'; ctx.beginPath(); ctx.arc(yx, fy, 34, 0, Math.PI * 2); ctx.fill();
    text(ctx, 'You', yx, fy, 16, '#fff', 800);
    text(ctx, elapsed >= 3300 ? 'Your turn: which line matches the standard? (1 = A, 2 = B, 3 = C)' : 'Others are answering…', W / 2, H - 28, 18, '#111', 600);
  },
  score(t, r) { return r == null ? false : r === t.correctResponse; },
  simulate(p, t, rng) {
    // Simulated: conformity propensity from the participant model (not a real-study rate).
    let resp = drawCorrect(p, rng, -1.5) ? t.correctResponse : rng.pick(['A', 'B', 'C'].filter((x) => x !== t.correctResponse));
    if (t.condition === 'critical' && rng.random() < p.conformity) resp = t.conf;
    return { response: resp, rt: 3400 + drawRT(p, rng, { mu: 900 }).rt };
  },
  analyse(rows) {
    const crit = rows.filter((r) => r.condition === 'critical' && r.response !== ''), neu = rows.filter((r) => r.condition === 'neutral' && r.response !== '');
    const conformed = crit.filter((r) => r.response === field(r.stimulus, 'conf')).length;
    const conf = crit.length ? conformed / crit.length : NaN;
    const neuErr = neu.length ? neu.filter((r) => !isOk(r)).length / neu.length : NaN;
    const lines = [
      `Critical trials (group unanimously wrong): you agreed with the group on ${conformed} of ${crit.length} (${pct(conf)} conformity)`,
      `Neutral trials (group correct): error rate ${pct(neuErr)} — shows how easy the judgement is when alone`,
      'Compare: the original Asch studies are recorded in facts.json as F-ASCH; their figures are still under verification, so none are shown here.',
      'This is one person on a few trials — individual results vary a lot and say nothing about character.',
    ];
    return { lines, stats: { conformity: conf, neutralErrors: neuErr },
      chart: (ch) => ch.bar([{ name: 'critical: conformed', value: (conf || 0) * 100 }, { name: 'neutral: errors', value: (neuErr || 0) * 100 }], { label: 'Asch-style task: your responses', yl: '%', yr: [0, 100] }) };
  },
}, SOC);

// ---------------------------------------------------------------- Prisoner's dilemma
const PAY = { CC: [3, 3], CD: [0, 5], DC: [5, 0], DD: [1, 1] }; // T=5 R=3 P=1 S=0
const OPPS = [
  { key: 'tft', name: 'Kiran', strategy: 'Tit-for-tat' },
  { key: 'alld', name: 'Saad', strategy: 'Always defect' },
  { key: 'allc', name: 'Mehr', strategy: 'Always cooperate' },
  { key: 'random', name: 'Bilqis', strategy: 'Random' },
  { key: 'grudger', name: 'Tariq', strategy: 'Grudger' },
];
/** Strategy move given the other player's past moves. */
function stratMove(key, other, rnd) {
  if (key === 'tft') return other.length ? other[other.length - 1] : 'C';
  if (key === 'alld') return 'D';
  if (key === 'allc') return 'C';
  if (key === 'random') return rnd() < 0.5 ? 'C' : 'D';
  if (key === 'grudger') return other.includes('D') ? 'D' : 'C';
  return 'C';
}
function tournament(rounds = 10, seed = 77) {
  const r = mkRng(seed), tot = {};
  OPPS.forEach((o) => { tot[o.key] = 0; });
  for (let i = 0; i < OPPS.length; i++) for (let j = i; j < OPPS.length; j++) {
    const a = [], b = [];
    for (let k = 0; k < rounds; k++) {
      const ma = stratMove(OPPS[i].key, b, r.random), mb = stratMove(OPPS[j].key, a, r.random);
      a.push(ma); b.push(mb);
      const [pa, pb] = PAY[ma + mb];
      tot[OPPS[i].key] += pa; if (i !== j) tot[OPPS[j].key] += pb;
    }
  }
  return OPPS.map((o) => ({ name: o.strategy, score: tot[o.key] })).sort((x, y) => y.score - x.score);
}
const prisonersDilemma = Object.assign({
  id: 'prisoners_dilemma', title: 'Prisoner’s dilemma tournament',
  purpose: 'To experience the tension between individual gain and mutual cooperation in a repeated prisoner’s dilemma against different strategies.',
  instructions: '<p>Each round, choose <b>Cooperate</b> (<kbd>1</kbd>) or <b>Defect</b> (<kbd>2</kbd>); your partner chooses at the same time. Points: both cooperate 3 each; both defect 1 each; if one defects and the other cooperates, the defector gets 5 and the cooperator 0.</p><p>You play several rounds with each of five simulated partners, each following a fixed strategy that is revealed at the end.</p>',
  estimateMin: 4, practice: 0, fix: 200, iti: 400, timeout: null, background: '#f8fafc',
  response: { type: 'choice', choices: [{ value: 'C', label: 'Cooperate' }, { value: 'D', label: 'Defect' }] },
  buildTrials(rng, opts) {
    const rounds = opts.trials ? Math.max(1, Math.ceil(opts.trials / OPPS.length)) : opts.quick ? 3 : 6;
    const out = [];
    rng.shuffle(OPPS.map((_, i) => i)).forEach((oi) => { for (let r = 1; r <= rounds; r++) out.push({ condition: OPPS[oi].key, opp: oi, round: r, rounds, stimulus: `${OPPS[oi].key}:round=${r}` }); });
    return out;
  },
  init() { return { pd: {} }; },
  prepare(t, state, rng) {
    state.pd = state.pd || {};
    const h = state.pd[t.condition] = state.pd[t.condition] || { you: [], them: [], youPts: 0, themPts: 0 };
    t.oppMove = stratMove(t.condition, h.you, () => rng.random());
    t.stimulus = `${t.condition}:round=${t.round}:them=${t.oppMove}`;
  },
  draw(ctx, t, W, H, elapsed, state) {
    const o = OPPS[t.opp], h = (state && state.pd && state.pd[t.condition]) || { you: [], them: [], youPts: 0, themPts: 0 };
    const lastThem = h.them[h.them.length - 1];
    drawFace(ctx, W * 0.22, H * 0.4, 190, lastThem === 'D' ? { 12: 0.3, 14: 0.5, unilateral: 1 } : lastThem === 'C' ? { 6: 0.5, 12: 0.7 } : {}, Object.assign(look(t.opp + 6), { label: `${o.name} (simulated partner)` }));
    text(ctx, `Round ${t.round} of ${t.rounds} with ${o.name}`, W * 0.64, 50, 22, '#111', 700);
    text(ctx, `Your points: ${h.youPts}    ${o.name}: ${h.themPts}`, W * 0.64, 86, 18, '#0F766E', 600);
    if (h.you.length) text(ctx, `Last round: you ${h.you[h.you.length - 1] === 'C' ? 'cooperated' : 'defected'}, ${o.name} ${lastThem === 'C' ? 'cooperated' : 'defected'}`, W * 0.64, 118, 16, '#334155', 500);
    const gx = W * 0.47, gy = H * 0.3, cw = W * 0.17, chh = 54;
    text(ctx, `${o.name} cooperates`, gx + cw * 1.5, gy - 16, 14, '#334155'); text(ctx, `${o.name} defects`, gx + cw * 2.5, gy - 16, 14, '#334155');
    [['C', 'You cooperate'], ['D', 'You defect']].forEach(([m, lab], i) => {
      text(ctx, lab, gx + cw * 0.5, gy + chh * (i + 0.5), 14, '#334155');
      ['C', 'D'].forEach((n, j) => { const [a, b] = PAY[m + n]; ctx.strokeStyle = '#94a3b8'; ctx.strokeRect(gx + cw * (j + 1), gy + chh * i, cw, chh); text(ctx, `you ${a} / them ${b}`, gx + cw * (j + 1.5), gy + chh * (i + 0.5), 14, '#111', 500); });
    });
    const hist = h.you.map((m, i) => m + h.them[i]).join('  ');
    if (hist) text(ctx, `History (you-them): ${hist}`, W * 0.64, H * 0.66, 15, '#334155', 500);
  },
  score() { return null; },
  update(state, t, result) {
    const h = state.pd && state.pd[t.condition]; if (!h) return;
    const you = result.response === 'D' ? 'D' : 'C';
    h.you.push(you); h.them.push(t.oppMove);
    const [a, b] = PAY[you + t.oppMove]; h.youPts += a; h.themPts += b;
  },
  simulate(p, t, rng, state) {
    // Simulated player: cooperativeness from the participant model, reciprocating recent defection.
    const h = state && state.pd && state.pd[t.condition];
    const lastThem = h && h.them.length ? h.them[h.them.length - 1] : null;
    const pc = lastThem === 'D' ? 0.3 * p.cooperativeness : lastThem === 'C' ? clamp(p.cooperativeness + 0.25, 0, 0.97) : p.cooperativeness;
    return { response: rng.random() < pc ? 'C' : 'D', rt: drawRT(p, rng, { mu: 1800 }).rt };
  },
  analyse(rows) {
    const per = OPPS.map((o) => {
      const r = rows.filter((x) => x.condition === o.key);
      let you = 0, them = 0, coop = 0;
      r.forEach((x) => { const m = x.response === 'D' ? 'D' : 'C', th = field(x.stimulus, 'them') || 'C'; const [a, b] = PAY[m + th]; you += a; them += b; if (m === 'C') coop++; });
      return { o, n: r.length, you, them, coop: r.length ? coop / r.length : NaN };
    }).filter((x) => x.n);
    const lines = per.map((x) => `${x.o.name} (${x.o.strategy}): you ${x.you} – ${x.them} them over ${x.n} rounds; you cooperated ${pct(x.coop)}`);
    lines.push(`Your total: ${S.sum(per.map((x) => x.you))} points`);
    const tour = tournament(10);
    lines.push(`Simulated round-robin tournament (each strategy vs every other and itself, 10 rounds): ${tour.map((t, i) => `${i + 1}. ${t.name} ${t.score}`).join(', ')}`);
    lines.push('Notice: defecting wins any single round, yet strategies that cooperate but retaliate tend to collect more points over repeated play.');
    return { lines, stats: { perOpponent: per.map((x) => ({ strategy: x.o.strategy, you: x.you, them: x.them })), tournament: tour },
      chart: (ch) => ch.bar(per.map((x) => ({ name: x.o.strategy, value: x.you })), { label: 'Your points per partner strategy', yl: 'points' }) };
  },
}, SOC);

// ---------------------------------------------------------------- IPIP Big Five
const PRACTICE_ITEMS = [ // Original practice items (NOT IPIP) — used only if src/data/ipip.json is unavailable.
  { id: 'P1', text: 'Enjoy starting conversations with new classmates.', scale: 'E', keyed: '+' },
  { id: 'P2', text: 'Go out of my way to help a stranger find their way.', scale: 'A', keyed: '+' },
  { id: 'P3', text: 'Finish assignments well before the deadline.', scale: 'C', keyed: '+' },
  { id: 'P4', text: 'Worry a lot about small things.', scale: 'N', keyed: '+' },
  { id: 'P5', text: 'Enjoy hearing ideas very different from mine.', scale: 'O', keyed: '+' },
  { id: 'P6', text: 'Prefer to spend breaks on my own.', scale: 'E', keyed: '-' },
  { id: 'P7', text: 'Find it hard to forgive small slights.', scale: 'A', keyed: '-' },
  { id: 'P8', text: 'Leave my notes in a mess.', scale: 'C', keyed: '-' },
  { id: 'P9', text: 'Stay calm under pressure.', scale: 'N', keyed: '-' },
  { id: 'P10', text: 'Prefer routines to new experiences.', scale: 'O', keyed: '-' },
];
const SCALES = ['E', 'A', 'C', 'N', 'O'];
const SCALE_NAMES = { E: 'Extraversion', A: 'Agreeableness', C: 'Conscientiousness', N: 'Neuroticism', O: 'Openness/Intellect' };
let ipipCache = null;
function ipipItems() {
  if (ipipCache) return ipipCache;
  try {
    const d = require('../../data/ipip.json');
    if (d && Array.isArray(d.items) && d.items.length >= 10) ipipCache = { items: d.items.map((it) => ({ id: 'ipip' + it.id, text: it.text, scale: it.scale, keyed: it.keyed })), source: 'IPIP 50-item Big-Five markers (public domain, ipip.ori.org)' };
  } catch (e) { /* fall back below */ }
  if (!ipipCache) ipipCache = { items: PRACTICE_ITEMS, source: 'Original practice items (not IPIP) — IPIP item file unavailable' };
  return ipipCache;
}
const LIKERT = [{ value: 1, label: '1 Very inaccurate' }, { value: 2, label: '2 Moderately inaccurate' }, { value: 3, label: '3 Neither' }, { value: 4, label: '4 Moderately accurate' }, { value: 5, label: '5 Very accurate' }];
const simItem = (trait, keyed, rnd) => { let v = 3 + (trait - 3) * 0.9 + rnd.normal(0, 0.8); if (keyed === '-') v = 6 - v; return clamp(Math.round(v), 1, 5); };

const ipipBig5 = {
  id: 'ipip_big5', title: 'IPIP Big Five + reliability', week: 13, panel: 'personality', zone: 'library', apa: '1.2', domain: 'IndDiff', hec: 'S2 Theories of Personality',
  purpose: 'To experience a public-domain Big Five questionnaire and learn how scale scores and internal consistency (Cronbach’s α) are computed. For learning only, not a diagnosis.',
  instructions: '<p><b>For learning only, not a diagnosis.</b> Rate how accurately each statement describes you as you generally are now (keys <kbd>1</kbd>–<kbd>5</kbd>). There are no right or wrong answers. Results show scale averages and reliability statistics only — they are not interpreted or used to label you.</p><p>Items: International Personality Item Pool (public domain).</p>',
  estimateMin: 6, practice: 0, fix: 150, iti: 250, timeout: null, background: '#f8fafc',
  response: { type: 'choice', choices: LIKERT },
  factRefs: ['F-IPIP'],
  buildTrials(rng, opts) {
    const { items } = ipipItems();
    let pick;
    if (opts.trials) {
      const per = {}; SCALES.forEach((s) => { per[s] = items.filter((it) => it.scale === s); });
      pick = []; let k = 0;
      while (pick.length < opts.trials) { const s = SCALES[k % 5], list = per[s]; const it = list[Math.floor(k / 5) % Math.max(1, list.length)]; if (it) pick.push(it); k++; if (k > 5000) break; }
    } else if (opts.quick) { const cnt = {}; pick = items.filter((it) => (cnt[it.scale] = (cnt[it.scale] || 0) + 1) <= 2); }
    else pick = items.slice();
    return pick.map((it, i) => ({ condition: it.scale, itemId: it.id, keyed: it.keyed, text: it.text, stimulus: `${it.id}:${it.scale}${it.keyed}${i >= items.length ? ':repeat' : ''}` }));
  },
  draw(ctx, t, W, H) {
    text(ctx, 'How accurately does this describe you?', W / 2, H * 0.22, 20, '#334155', 600);
    wrap(ctx, `"${t.text}"`, W / 2, H * 0.4, W * 0.8, 32, '#111', 700);
    text(ctx, '1 Very inaccurate  ·  2  ·  3 Neither  ·  4  ·  5 Very accurate', W / 2, H * 0.62, 17, '#334155', 500);
    text(ctx, 'For learning only, not a diagnosis.', W / 2, H - 56, 15, '#9f1239', 600);
    text(ctx, ipipItems().source, W / 2, H - 32, 12, '#64748b', 500);
  },
  score() { return null; },
  simulate(p, t, rng) { return { response: simItem((p.big5 && p.big5[t.condition]) || 3, t.keyed, rng), rt: drawRT(p, rng, { mu: 2600 }).rt }; },
  analyse(rows) {
    const { items } = ipipItems();
    const byId = {}; items.forEach((it) => { byId[it.id] = it; });
    const resp = {}; rows.forEach((r) => { const id = String(r.stimulus).split(':')[0]; if (byId[id] && r.response !== '') resp[id] = +r.response; });
    const used = Object.keys(resp).map((id) => byId[id]);
    const scores = PM.scoreIPIP(used, used.map((it) => resp[it.id]));
    const coh = cohort(mkRng(4242), 40);
    const rnd = mkRng(99);
    const alpha = {};
    for (const s of SCALES) {
      const its = used.filter((it) => it.scale === s);
      if (its.length < 2) { alpha[s] = NaN; continue; }
      const scored = (it, v) => (it.keyed === '-' ? 6 - v : v);
      const m = coh.map((p) => its.map((it) => scored(it, simItem(p.big5[s], it.keyed, rnd))));
      m.push(its.map((it) => scored(it, resp[it.id])));
      try { alpha[s] = PM.cronbachAlpha(m); } catch (e) { alpha[s] = NaN; }
    }
    const fmt = (v) => (Number.isFinite(v) ? v.toFixed(2) : '—');
    const lines = [
      'For learning only, not a diagnosis. Scores are descriptive averages and are not interpreted.',
      `Your scale means (1–5, reverse-keyed items scored 6 − x): ${SCALES.map((s) => `${s} ${scores[s] ? fmt(scores[s].mean) : '—'}`).join(', ')}`,
      `Cronbach's α per scale (Simulated data: 40 simulated classmates + your responses): ${SCALES.map((s) => `${s} ${fmt(alpha[s])}`).join(', ')}`,
      `Items answered: ${used.length}. Fewer items per scale usually means lower α (see Spearman–Brown).`,
      `Scales: ${SCALES.map((s) => `${s} = ${SCALE_NAMES[s]}`).join('; ')}.`,
    ];
    return { lines, stats: { means: SCALES.reduce((o, s) => { o[s] = scores[s] ? scores[s].mean : NaN; return o; }, {}), alpha },
      chart: (ch) => ch.bar(SCALES.map((s) => ({ name: s, value: scores[s] ? scores[s].mean : 0 })), { label: 'Your scale means (1–5) — for learning only', yl: 'mean', yr: [0, 5] }) };
  },
};

// ---------------------------------------------------------------- Facial-expression recognition
const EMO = ['happiness', 'sadness', 'surprise', 'fear', 'anger', 'disgust', 'neutral'];
const CONFUSE = { happiness: 'neutral', sadness: 'neutral', surprise: 'fear', fear: 'surprise', anger: 'disgust', disgust: 'anger', neutral: 'sadness' };
const scaleAUs = (emo, k) => { const o = {}; const src = EMOTIONS[emo] || {}; for (const key of Object.keys(src)) o[key] = key === 'unilateral' ? src[key] : src[key] * k; return o; };
const faceRecognition = {
  id: 'face_recognition', title: 'Facial-expression recognition (FACS)', week: 12, panel: 'emotion', zone: 'clinic', apa: '1.1', domain: 'Bio/Social', hec: 'S1 Introduction to Psychology',
  purpose: 'To test how accurately you recognise basic emotional expressions on procedurally generated FACS faces at different intensities.',
  instructions: '<p>A face will appear. Choose the emotion it shows (keys <kbd>1</kbd>–<kbd>7</kbd>): happiness, sadness, surprise, fear, anger, disgust or neutral. Some expressions are subtle.</p><p>Faces are original procedural drawings built from FACS action units — not photographs.</p>',
  estimateMin: 4, practice: 2, fix: 400, iti: 400, timeout: 8000, background: '#e5e7eb',
  response: { type: 'choice', choices: EMO.map((e) => ({ value: e, label: e[0].toUpperCase() + e.slice(1) })) },
  factRefs: ['F-EKMAN'],
  buildTrials(rng, opts) {
    const ints = opts.quick || opts.practice === true ? [0.6, 1.0] : [0.4, 0.7, 1.0];
    const looks = opts.quick || opts.practice === true ? 1 : 2;
    const n = opts.trials || EMO.length * ints.length * looks;
    const out = [];
    let rep = 0;
    while (out.length < n) {
      const block = [];
      for (const e of EMO) for (const k of ints) for (let l = 0; l < looks; l++) {
        const kk = e === 'neutral' ? 0 : k, li = rng.int(0, 11);
        block.push({ condition: e, intensity: kk, look: li, correctResponse: e, stimulus: `${e}@${kk.toFixed(1)}:face${li}${rep ? ':r' + rep : ''}` });
      }
      out.push(...rng.shuffle(block)); rep++;
    }
    return out;
  },
  draw(ctx, t, W, H) {
    drawFace(ctx, W / 2, H * 0.45, Math.min(320, H * 0.55), scaleAUs(t.condition, t.intensity), look(t.look));
    text(ctx, 'Which emotion is shown?', W / 2, 40, 22, '#111', 700);
  },
  score(t, r) { return r == null ? false : r === t.correctResponse; },
  simulate(p, t, rng) {
    // Simulated effect size: harder for subtle faces and for fear/disgust (illustrative, not real norms).
    const diff = { happiness: -1, surprise: 0, sadness: 0.5, anger: 0.8, disgust: 1.0, fear: 1.4, neutral: 0.3 }[t.condition] + (t.condition === 'neutral' ? 0 : (1 - t.intensity) * 2);
    const ok = drawCorrect(p, rng, diff);
    return { response: ok ? t.condition : (rng.random() < 0.7 ? CONFUSE[t.condition] : rng.pick(EMO.filter((e) => e !== t.condition))), rt: drawRT(p, rng, { mu: 1100, effect: diff * 120 }).rt };
  },
  analyse(rows) {
    const acc = EMO.map((e) => meanOr(rows.filter((r) => r.condition === e).map((r) => (isOk(r) ? 1 : 0))));
    const conf = {};
    rows.filter((r) => !isOk(r) && r.response !== '').forEach((r) => { const k = `${r.condition} → ${r.response}`; conf[k] = (conf[k] || 0) + 1; });
    const top = Object.entries(conf).sort((a, b) => b[1] - a[1]).slice(0, 4);
    const ints = Array.from(new Set(rows.filter((r) => r.condition !== 'neutral').map((r) => String(r.stimulus).split('@')[1].split(':')[0]))).sort();
    const accInt = ints.map((k) => meanOr(rows.filter((r) => r.condition !== 'neutral' && String(r.stimulus).split('@')[1].startsWith(k)).map((r) => (isOk(r) ? 1 : 0))));
    const overall = meanOr(rows.map((r) => (isOk(r) ? 1 : 0)));
    const lines = [
      `Overall accuracy: ${pct(overall)} (${rows.length} faces; chance = 14%)`,
      `By emotion: ${EMO.map((e, i) => `${e} ${pct(acc[i])}`).join(', ')}`,
      `By intensity (emotional faces): ${ints.map((k, i) => `${k} → ${pct(accInt[i])}`).join(', ') || '—'}`,
      `Most common confusions: ${top.length ? top.map(([k, v]) => `${k} (${v})`).join(', ') : 'none'}`,
      'Faces are built from FACS action-unit prototypes (F-EKMAN); intensities are illustrative.',
    ];
    return { lines, stats: { overall, byEmotion: EMO.reduce((o, e, i) => { o[e] = acc[i]; return o; }, {}) },
      chart: (ch) => ch.bar(EMO.map((e, i) => ({ name: e, value: (acc[i] || 0) * 100 })), { label: 'Recognition accuracy by emotion', yl: '%', yr: [0, 100] }) };
  },
};

module.exports = [conservation, falseBelief, asch, prisonersDilemma, ipipBig5, faceRecognition];
